/bin/bash -lc "cd [workspace path] && python3 -c \"
import numpy as np
data = np.load('source_pixels.npz')['rgb']
def carmask(f):
    r,g,b = f[...,0].astype(int), f[...,1].astype(int), f[...,2].astype(int)
    return (g>110)&(b>110)&(r<180)&(g-r>15)&(b-r>5)
for i in range(0,96,3):
    f = data[i]
    m = carmask(f)
    ys,xs = np.nonzero(m)
    if len(xs):
        print(f'{i:2d} n={len(xs):4d} cx={xs.mean():6.1f} cy={ys.mean():6.1f} x[{xs.min():3d},{xs.max():3d}] y[{ys.min():3d},{ys.max():3d}]')
    else:
        print(i, 'none')
\""
